///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.bns.BnsPanelToGroupBox(pnl_Info);

        // 공통콤보
        const arrCid = [];
        arrCid.push({
            cid: '02475',
            cnm: 'cmb_CurrTpCd'
        }); // 발행통화
        $c.bns.fn_SetBnsComboToCode("ULDBNS20005.xml", dts_Temp, arrCid);

        // 파라미터설정
        scwin.setParam();
        // Exa DB체크
        if (js_svrGubun === 'dr') {
            await $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
            // return false;

        } else {
            $c.bns.fn_BnsCheckExaDb("ULDBNS20005.xml", dts_CheckExa, '1');
        }

        // showObj(cmb_CurrTpCd, false);    //통화단위 숨기기(요청사항)
        // 숨기기
        if (scwin.vs_G_GB === "01") {
            pnl_new.hide();
        } else {
            pnl_org.hide();
            btn_SearchEx.hide();
            btn_Calc.hide();
        }
        // 조회
        label_6.hide();
        chk_TrdYn.hide();
        label_3.hide();
        chk_KseMemYn.hide();
        scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

