/**
 * @method
 * @name dts_Anulfee_OnLoadCompleted
 * @description dts_Anulfee 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Anulfee_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vRowCount = rowcount;
        txb_ChrgNm.setValue(js_emp_nm);
        if (rowcount > 0) {
            if (scwin.vIsuNm !== '') {
                txb_IsuNm.setValue(scwin.vIsuNm);
            }

            // KRW이면 기준환율 입력불가
            if (dts_Anulfee.getCellData(1, 'CURR_TP_CD') === '1') {
                edt_BasExchg.setDisabled(true);
            }
            // 수수료조회
            if (dts_Anulfee.getCellData(1, 'CHK_IDX') === 0) {
                scwin.searchFee();
            }
            scwin.exchMbr();
            /*
            //자동저장
            if(getObjectValue(cmb_ListFeePayYn) == 'E'
            	&& getObjectValue(cmb_AnulfeePayYn) == 'E') {
            	fn_Save();
            }
             */

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20005.dts_Anulfee_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Calc_OnLoadCompleted
 * @description dts_Calc 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Calc_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount > 0) {
            if (cmb_BndListFeeExmptRsnCd.getValue() !== '') {
                edt_ListFee.setValue('0');
                edt_BndAnulfee.setValue('0');
            }
            // 환율적용
            else if (scwin.vFeeTpCd === '1') {
                scwin.vFeeTpCd = '';
                edt_ListFee.setValue(dts_Calc.getCellData(1, 'LIST_FEE'));
            }
            // 수정계산
            else {
                if (cmb_CurrTpCd.getValue() !== '1') {
                    if (dts_Calc.getCellData(1, 'EXCHG_RT') !== '') {
                        edt_ListFee.setValue(dts_Calc.getCellData(1, 'LIST_FEE'));
                    }
                } else {
                    edt_ListFee.setValue(dts_Calc.getCellData(1, 'LIST_FEE'));
                }

                // 연부과금
                if (cmb_AnulfeePayYn.getValue() === 'E') {
                    edt_BndAnulfee.setValue('0');
                } else {
                    edt_BndAnulfee.setValue(dts_Calc.getCellData(1, 'BND_ANULFEE'));
                }
            }
            txb_Term.setValue(dts_Calc.getCellData(1, 'TERM'));
            edt_BasExchg.setValue(dts_Calc.getCellData(1, 'EXCHG_RT'));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20005.dts_Calc_OnLoadCompleted" });
    }
};

