///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 기본정보를 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let dsNm = 'BNS_ANULFEE_DTL';
    let qryId = "";
    let param = '';
    if (scwin.vs_G_GB === "01") {
        qryId = 'lds.stf.bnsnew.select.readFeeBasInfo01';
        param += '&{P}V_BND_APPL_ID=' + scwin.vs_G_BND_APPL_ID;
        param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vs_G_BND_LIST_PROCS_TP_CD;
    } else {
        qryId = 'lds.stf.bnsnew.select.readFeeBasInfo03';
        param += '&{P}V_GRP_PROCS_DD=' + scwin.vs_G_GRP_PROCS_DD;
        param += '&{P}V_GRP_PROCS_TM=' + scwin.vs_G_GRP_PROCS_TM;
    }
    $c.bns.fn_SearchBns("ULDBNS20005.xml", dts_Anulfee, dsNm, qryId, param);
};

/**
 * @method
 * @name searchFee
 * @description 수수료 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchFee = function() {
    let param = '';
    param += '&{P}V_BND_APPL_ID=' + scwin.vBndApplId;
    param += '&{P}V_LIST_AMT=' + edt_ListAmt.getValue();
    param += '&{P}V_REDMPT_DD=' + edt_RedmptDd.getValue();
    param += '&{P}V_LIST_DD=' + edt_ListDd.getValue();
    param += '&{P}V_CURR_TP_CD=' + cmb_CurrTpCd.getValue();
    param += '&{P}V_EXCHG_RT=' + edt_BasExchg.getValue();
    param += '&{P}V_BND_LIST_PROCS_TP_CD=' + '1';
    let dsNm = 'BNS_ANULFEE_DTL';
    let qryId = 'lds.stf.bnscommon.select.readCalcFee';
    $c.bns.fn_SearchBns("ULDBNS20005.xml", dts_Calc, dsNm, qryId, param);
};

/**
 * @method
 * @name save
 * @description 상장수수료 및 연부과금에서  저장 시, 수정처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkData() > 0) return;
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "수수료등록"))) return;

    /**
     *     - 변경된 데이터가 없더라도 데이터셋 전송하여 접수 진행
     */
    dts_Anulfee.UseChangeInfo = "False";
    let url = "/bns/ListFeeAndAnulfee.do?method=updateNewListFee";
    url += "&SCREN_ID=" + "ULDBNS20005.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Anulfee)";
    trs_Save.Post();
};

/**
 * @method
 * @name checkData
 * @description 입력을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function() {
    if (txb_IsuNm.getValue() === '') {
        await $c.win.alert('등록할 데이타가 없습니다.');
        return 1;
    }
    if (cmb_ListFeePayYn.getValue() === '') {
        await $c.win.alert('상장수수료 납부여부 선택하십시오.');
        return 1;
    }
    if (cmb_AnulfeePayYn.getValue() === '') {
        await $c.win.alert('연부과금 납부여부 선택하십시오.');
        return 1;
    }
    if (edt_BndAnulfee.getValue() === '') {
        await $c.win.alert('연부과금 수수료금액을 입력하십시오.');
        return 1;
    }
    if (edt_ListFee.getValue() === '') {
        await $c.win.alert('상장수수료 수수료금액을 입력하십시오.');
        return 1;
    }
    if (cmb_ListFeePayYn.getValue() === '3' &&
        cmb_BndListFeeExmptRsnCd.getValue() === '') {
        await $c.win.alert('상장수수료 면제시에는 면제사유를 선택하십시오.');
        return 1;
    }
    if (cmb_ListFeePayYn.getValue() === '3' &&
        edt_ListFee.getValue() !== '0') {
        await $c.win.alert('상장수수료 면제시에는 상장수수료를 0원으로 입력하십시오.');
        return 1;
    }
    if (cmb_AnulfeePayYn.getValue() === '3' &&
        cmb_BndAnulfeeExmptRsnCd.getValue() === '') {
        await $c.win.alert('연부과금 면제시에는 면제사유를 선택하십시오.');
        return 1;
    }
    if (cmb_AnulfeePayYn.getValue() === '3' &&
        edt_BndAnulfee.getValue() !== '0') {
        await $c.win.alert('연부과금 면제시에는 연부과금액을 0원으로 입력하십시오.');
        return 1;
    }

    // 상장수수료,연부과금 면제이면 입금일 체크하지 않는다.
    if (cmb_ListFeePayYn.getValue() === 'E' && cmb_AnulfeePayYn.getValue() === 'E') {
        return 0;
    }
    if (edt_FeeDepoDd.getValue() === '') {
        await $c.win.alert('입금일을 입력하십시오.');
        return 1;
    }
    if ($c.bns.fn_CheckDateObj(edt_FeeDepoDd, "입금일")) {
        return 1;
    }
    // 메시지 추가 입금일이 오늘 이후 날짜일 경우 확인메시지 추가
    if (edt_FeeDepoDd.getValue() > $c.ut.cGetToday('yyyymmdd')) {
        if (!window.confirm('입금일이 오늘 이후 날짜입니다. 계속 진행하시겠습니까?')) return 1;
    }
    return 0;
};

/**
 * @method
 * @name calc
 * @description 수수료 수정계산
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calc = async function() {
    if (edt_ListAmt.getValue() === '' ||
        edt_ListDd.getValue() === '' ||
        edt_RedmptDd.getValue() === '') {
        await $c.win.alert('상장금액, 상장일, 상환일을 확인하세요');
        return;
    }
    if (cmb_CurrTpCd.getValue() !== '' &&
        cmb_CurrTpCd.getValue() !== '1') {
        if (edt_BasExchg.getValue() === '') {
            await $c.win.alert('기준환율을 입력바랍니다.');
            return;
        }
    }
    scwin.searchFee();
};

/**
 * @method
 * @name exApply
 * @description 환율적용 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.exApply = async function() {
    if (cmb_CurrTpCd.getValue() !== '1') {
        if (edt_BasExchg.getValue() === '') {
            await $c.win.alert('기준환율을 입력바랍니다.');
            return;
        }
        scwin.vFeeTpCd = '1';
        scwin.searchFee();
    } else {
        await $c.win.alert('외화표시채권일때만 선택합니다.');
        edt_BasExchg.setValue('');
    }
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        let arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.vBndApplId = arrPar[0].BND_APPL_ID;
        scwin.vListDd = arrPar[0].LIST_DD;
        scwin.vIsuNm = arrPar[0].ISU_NM;
        scwin.vMktactTpCd = arrPar[0].MKTACT_TP_CD;
        scwin.vs_G_GRP_PROCS_DD = arrPar[0].GRP_PROCS_DD;
        scwin.vs_G_GRP_PROCS_TM = arrPar[0].GRP_PROCS_TM;
        scwin.vs_G_BND_APPL_ID = arrPar[0].BND_APPL_ID;
        scwin.vs_G_BND_LIST_PROCS_TP_CD = arrPar[0].BND_LIST_PROCS_TP_CD;
        scwin.vs_G_GB = arrPar[0].GRP_GB;
    }
};

/**
 * @method
 * @name exchMbr
 * @description 거래소회원 체크 여부
 * @returns {void}
 * @hidden N
 */
scwin.exchMbr = function() {
    if (dts_Anulfee.getCellData(1, "KSE_MEM_YN") === 'Y') {
        chk_KseMemYn.setValue(1);
    } else {
        chk_KseMemYn.setValue(0);
    }
};

/**
 * @method
 * @name close
 * @description 팝업 닫기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.close = async function() {
    await $c.win.closePopup();
};
